}

export interface ScoreSnapshot {
  period: string; // e.g., "Term 1"
  totalScore: number;
  averageScore: number;
  scores: Record<string, number>;
  ranks?: Record<string, number>; // Imported ranks
  schoolRank?: number; // Imported school total rank
  isComplete?: boolean; // Data completeness flag
}

export interface StudentRecord {
  id: string;
  name: string;
  class: string;
  scores: Record<string, number>;
  totalScore: number;
  averageScore: number;
  history: ScoreSnapshot[]; 
}

export interface ExamEntity {
  id: string;
  name: string;
  weight: number;
  isComplete: boolean;
  fileCount: number;
}

export interface AnalysisState {
  students: StudentRecord[];
  subjects: string[];
  classes: string[];
  schoolStats: {
    average: number;
    max: number;
    min: number;
    subjectStats: Record<string, { average: number; max: number; min: number }>;
    distribution: { name: string; value: number; color: string }[];
  };
}

